// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  predicateInfo,
  statementCards,
  statementTokens,
} from "../../../main/frontend/graph-explorer/statement-details.ts";
import { sparqlNodeId } from "../../../main/frontend/graph-explorer/rdf-terms.ts";

const uri = (value) => ({ type: "uri", value });
const literal = (value, extra = {}) => ({ type: "literal", value, ...extra });

test("an edge's statement as SPARQL tokens, none when a blank node takes part", () => {
  assert.deepEqual(
    statementTokens({ source: "urn:a", predicate: "urn:p", target: sparqlNodeId(literal("x", { "xml:lang": "en" })) }),
    { subject: "<urn:a>", predicate: "<urn:p>", object: '"x"@en' },
  );
  assert.equal(statementTokens({ source: sparqlNodeId({ type: "bnode", value: "b" }), predicate: "urn:p", target: "urn:a" }), null);
});

test("annotation rows become one card per resource: reifiers, then reifications, then references", () => {
  const cards = statementCards([
    { kind: literal("reference"), about: uri("urn:alice"), property: uri("urn:believes") },
    { kind: literal("reifier"), about: uri("urn:claim"), property: uri("urn:source"), value: uri("urn:wiki") },
    { kind: literal("reifier"), about: uri("urn:claim"), property: uri("urn:date"), value: literal("2026") },
    { kind: literal("reification"), about: uri("urn:stmt") },
    { kind: literal("nonsense"), about: uri("urn:x") },
  ]);
  assert.deepEqual(
    cards.map((card) => [card.kind, card.about.value, card.rows.map((row) => [row.property, row.value?.value])]),
    [
      ["reifier", "urn:claim", [["urn:source", "urn:wiki"], ["urn:date", "2026"]]],
      ["reification", "urn:stmt", []],
      ["reference", "urn:alice", [["urn:believes", undefined]]],
    ],
  );
});

test("predicate rows are sorted into description, domain, range, super-properties and inverse", () => {
  const info = predicateInfo([
    { property: uri("http://www.w3.org/2000/01/rdf-schema#comment"), value: literal("Knows someone", { "xml:lang": "en" }) },
    { property: uri("http://www.w3.org/2000/01/rdf-schema#domain"), value: uri("urn:Person") },
    { property: uri("http://schema.org/rangeIncludes"), value: uri("urn:Person") },
    { property: uri("http://www.w3.org/2000/01/rdf-schema#subPropertyOf"), value: uri("urn:related") },
    { property: uri("http://www.w3.org/2002/07/owl#inverseOf"), value: uri("urn:knownBy") },
  ]);
  assert.deepEqual(info, {
    descriptions: [{ text: "Knows someone", language: "en" }],
    domain: ["urn:Person"],
    range: ["urn:Person"],
    superProperties: ["urn:related"],
    inverse: ["urn:knownBy"],
  });
});
